'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Float32Array = require( '@stdlib/array/float32' );
var snanstdev = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof snanstdev, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 4', function test( t ) {
	t.strictEqual( snanstdev.length, 4, 'has expected arity' );
	t.end();
});

tape( 'the function calculates the standard deviation of a strided array, ignoring NaN values', function test( t ) {
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, -4.0, NaN, 5.0, 0.0, 3.0 ] );
	v = snanstdev( x.length, 1, x, 1 );
	t.strictEqual( typeof v, 'number', 'returns a number' );

	x = new Float32Array( [ -4.0, NaN, -4.0 ] );
	v = snanstdev( x.length, 1, x, 1 );
	t.strictEqual( v, 0.0, 'returns expected value' );

	x = new Float32Array( [ NaN, 4.0 ] );
	v = snanstdev( x.length, 1, x, 1 );
	t.strictEqual( v, 0.0, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns `NaN`', function test( t ) {
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 3.0 ] );

	v = snanstdev( 0, 1, x, 1 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = snanstdev( -1, 1, x, 1 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a `stride` parameter equal to `0`, the function returns `0` if the first element is not NaN', function test( t ) {
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 3.0 ] );

	v = snanstdev( x.length, 1, x, 0 );
	t.strictEqual( v, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `ndarray` method which calculates the standard deviation using alternative indexing semantics', function test( t ) {
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, NaN, -4.0, 5.0, 0.0, 3.0 ] );
	v = snanstdev.ndarray( x.length, 1, x, 1, 0 );
	t.strictEqual( typeof v, 'number', 'returns a number' );

	t.end();
});
